#include "visit_message_receipt_profile.hpp"
#include <set>
namespace hanmo::resident {
Outcome<Integer>decode_visit_message_receipt_profile_version(const BoundaryValue&scenario,const std::vector<StableId>&capabilities){try{using namespace boundary;std::set<StableId>keys;for(const auto&row:object(scenario,"scenario"))if(!keys.insert(row.first).second)fail("DuplicateVisitMessageReceiptProfileField",row.first);const auto*profile=scenario.find("visit_message_receipt_profile");if(!profile)return {true,0,{}};const auto name=string(*profile,"visit_message_receipt_profile");const Integer version=name=="permanent_visit_message_results_v1"?1:name=="permanent_visit_message_results_v2"?2:0;if(!version)unsupported("UnsupportedVisitMessageReceiptProfile","visit_message_receipt_profile");auto original=decode_visit_message_profile_version(scenario,capabilities);if(!original.ok)return {false,{},original.error};if(!original.value)unsupported("VisitMessageReceiptOriginalRequired","visit_message_profile");const StableId capability=version==1?"visit_message_receipts_v1":"visit_message_receipts_v2";if(std::find(capabilities.begin(),capabilities.end(),capability)==capabilities.end())unsupported("VisitMessageReceiptCapabilityRequired",capability);return {true,version,{}};}catch(const boundary::DecodeFailure&e){return {false,{},e.error};}}
Outcome<bool>decode_visit_message_receipt_profile(const BoundaryValue&s,const std::vector<StableId>&c){auto version=decode_visit_message_receipt_profile_version(s,c);return version.ok?Outcome<bool>{true,version.value!=0,{}}:Outcome<bool>{false,false,version.error};}
Status validate_visit_message_receipt_layout(const std::vector<std::pair<StableId,StableId>>&modules,bool selected,bool original,const VisitMessageReceiptState*state){auto version=visit_message_receipt_selected_version(modules);if(!version.ok)return {false,{},version.error};if(bool(version.value)!=selected||bool(state)!=selected||(selected&&(!original||state->version!=version.value)))return common_failure("VisitMessageReceiptProfileMismatch");return common_success();}
Outcome<VisitMessageReceiptState>make_initial_visit_message_receipt_state(const CatalogIdentity&identity,const VisitMessageCatalog&messages){auto version=visit_message_receipt_selected_version(identity.module_versions);if(!version.ok)return {false,{},version.error};if(!version.value||messages.version<1||messages.version>3)return {false,{},common_failure("VisitMessageReceiptProfileRequired",{},ErrorKind::unsupported_capability).error};Integer selected_messages=0;for(const auto&row:identity.module_versions)if(row.first=="visit_messages")selected_messages=row.second=="1"?1:row.second=="2"?2:3;if(selected_messages!=messages.version)return {false,{},common_failure("VisitMessageReceiptOriginalSelectionMismatch").error};VisitMessageReceiptState state;state.version=version.value;return {true,std::move(state),{}};}
}
